import React, { useState } from 'react';
import { TextField, Button, Box, Typography, Paper } from '@mui/material';

const API = process.env.REACT_APP_API_URL || "http://localhost:5000/api";


export default function Signup() {
  const [form, setForm] = useState({ name: '', email: '', password: '' });
  const [msg, setMsg] = useState('');

  const handleChange = e => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg('');
    try {
      const res = await fetch(`${API}/auth/signup`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.msg || 'Signup failed');
      setMsg('Signup successful! You can now login.');
      setForm({ name: '', email: '', password: '' });
    } catch (err) {
      setMsg(err.message);
    }
  };

  return (
    <Paper elevation={3} sx={{ p: 4, maxWidth: 400, mx: 'auto', mt: 5 }}>
      <Typography variant="h5" sx={{ mb: 2 }}>Create Account</Typography>
      <form onSubmit={handleSubmit}>
        <TextField label="Name" name="name" fullWidth value={form.name} onChange={handleChange} sx={{ mb: 2 }} />
        <TextField label="Email" name="email" type="email" fullWidth value={form.email} onChange={handleChange} sx={{ mb: 2 }} />
        <TextField label="Password" name="password" type="password" fullWidth value={form.password} onChange={handleChange} sx={{ mb: 3 }} />
        <Button type="submit" variant="contained" fullWidth>Sign Up</Button>
      </form>
      {msg && <Typography color="primary" sx={{ mt: 2 }}>{msg}</Typography>}
    </Paper>
  );
}
